import{_ as r,o as l,c as s,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Over a Billion Requests Served per Day: Ensuring Everyone Is Happy with Our Ceph Clusters’...","description":"","frontmatter":{"title":"Over a Billion Requests Served per Day: Ensuring Everyone Is Happy with Our Ceph Clusters’...","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","QoS平台","质量服务","软件定义存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Over_a_Billion_Requests_Served_per_Day_-_Ensuring_Everyone_Is_Happy_with_Our_Ceph_Clusters_....md","filePath":"posts/2023/Over_a_Billion_Requests_Served_per_Day_-_Ensuring_Everyone_Is_Happy_with_Our_Ceph_Clusters_....md","lastUpdated":1780459816000}'),_={name:"posts/2023/Over_a_Billion_Requests_Served_per_Day_-_Ensuring_Everyone_Is_Happy_with_Our_Ceph_Clusters_....md"};function o(i,e,n,p,a,u){return l(),s("div",null,[...e[0]||(e[0]=[t('<p>Bloomberg的存储工程团队在会议上介绍了他们开发的软件定义分布式QRS系统，旨在确保其Ceph存储集群的性能满足用户需求。以下是对会议内容的总结：</p><h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><p><strong>主题：</strong> Bloomberg软件定义分布式QRS系统的介绍与实施细节</p><p><strong>时间：</strong> 具体时间</p><p><strong>地点：</strong> 具体地点</p><p><strong>参会人员：</strong> Nathan, Alex及相关技术和业务人员</p><p><strong>会议内容：</strong></p><ol><li><p><strong>介绍与背景</strong></p><ul><li>Nathan介绍了Bloomberg作为一家金融技术公司，其存储工程团队负责设计和维护所有存储解决方案，包括基于设备和软件定义的存储。</li><li>分布式存储团队专注于软件定义存储，主要产品包括基于Ceph的块存储（BCC）和对象存储（BCS）。</li></ul></li><li><p><strong>系统概述</strong></p><ul><li>系统目标是为Bloomberg的存储集群提供高性能，特别是在S3网关上实施QoS平台。</li><li>系统设计考虑了多站点设置，采用主动-被动配置，用户与主动集群交互，流量被复制到被动集群。</li></ul></li><li><p><strong>用户期望与系统目标</strong></p><ul><li>用户期望系统提供与Amazon S3类似的体验，包括高可用性、灵活的客户端SDK选择、可接受的带宽和延迟。</li><li>系统目标包括提供一致的性能体验、管理集群性能、以及提供集群活动的可见性。</li></ul></li><li><p><strong>QoS设计与实施</strong></p><ul><li>QoS系统设计考虑了层7（HTTP层）的操作，支持基于访问密钥和桶级别的流量控制。</li><li>实施细节包括使用HAProxy和Redis进行流量解析和聚合，自定义的syslog服务器和策略生成器用于实时监控和限制违规行为。</li></ul></li><li><p><strong>挑战与未来计划</strong></p><ul><li>面临的挑战包括实时监控集群、理解系统行为、以及分布式系统间的通信问题。</li><li>未来计划包括扩展系统的维度、动态调整配额、优先级管理、连接限制以及开源贡献。</li></ul></li></ol><p><strong>决定事项：</strong></p><ul><li>确认了QoS系统的设计和实施细节，以及未来的发展方向。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>继续开发和优化QoS系统，包括扩展功能和提高动态性。</li><li>探索更智能的请求成本分配方法。</li><li>考虑将系统开源，并寻求社区反馈以改进系统。</li></ul><p><strong>会议总结：</strong> Bloomberg的软件定义分布式QRS系统是基于Ceph构建的，旨在提供高性能和可扩展的存储解决方案。会议详细介绍了系统设计、实施细节和未来计划，强调了QoS平台在确保集群性能和用户满意度方面的重要性。</p>',13)])])}const h=r(_,[["render",o]]);export{d as __pageData,h as default};
